func toCoreSyntheticPage(in *pb.MuskdeerSyntheticPage) *core.SyntheticPage {
	if in == nil {
		return nil
	}
	out := &core.SyntheticPage{
		Total: in.Total,
	}
	for _, v := range in.Items {
		out.Items = append(out.Items, toCoreSyntheticRecord(v))
	}
	return out
}
func toCoreAccountSnapshot(in *pb.MuskdeerAccountSnapshot) *core.AccountSnapshot {
	if in == nil {
		return nil
	}
	out := &core.AccountSnapshot{
		AccountId:    in.AccountId,
		Symbol:       in.Symbol,
		ValidUntilMs: in.ValidUntilMs,
		Available:    in.Available,
		MarkPrice:    in.MarkPrice,
		ObservedAtMs: in.ObservedAtMs,
	}
	for _, v := range in.Orders {
		out.Orders = append(out.Orders, toCoreActiveOrder(v))
	}
	for _, v := range in.Positions {
		out.Positions = append(out.Positions, toCorePosition(v))
	}
	return out
}
